buffered_blake3_adapter:
// Ephemeral benchmark adapter. Buffer short inputs for BLAKE3's one-shot path.
pub(crate) struct ExperimentalHash {
    short: [u8; 1024],
    used: usize,
    long: Option<blake3::Hasher>,
}
impl ExperimentalHash {
    pub(crate) fn new() -> Self {
        Self { short: [0; 1024], used: 0, long: None }
    }
    pub(crate) fn update(&mut self, bytes: impl AsRef<[u8]>) {
        let bytes = bytes.as_ref();
        if let Some(h) = &mut self.long { h.update(bytes); }
        else if bytes.len() <= self.short.len() - self.used {
            self.short[self.used..self.used+bytes.len()].copy_from_slice(bytes);
            self.used += bytes.len();
        } else {
            let mut h = blake3::Hasher::new();
            h.update(&self.short[..self.used]); h.update(bytes); self.long = Some(h);
        }
    }
    pub(crate) fn finalize(self) -> [u8; 32] {
        match self.long {
            Some(h) => *h.finalize().as_bytes(),
            None => *blake3::hash(&self.short[..self.used]).as_bytes(),
        }
    }
    pub(crate) fn digest(bytes: impl AsRef<[u8]>) -> [u8; 32] { *blake3::hash(bytes.as_ref()).as_bytes() }
}
#[cfg(test)] mod tests {
    use super::*;
    #[test] fn buffered_matches_blake3_at_boundaries() {
        for len in [0,1,63,64,65,511,512,1023,1024,1025,4096] {
            let bytes: alloc::vec::Vec<u8> = (0..len).map(|i| (i % 251) as u8).collect();
            for chunk in [1,7,64,1024] {
                let mut h = ExperimentalHash::new();
                for part in bytes.chunks(chunk) { h.update(part); }
                assert_eq!(h.finalize(), *blake3::hash(&bytes).as_bytes());
            }
        }
    }
}
